('d1000000-0000-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000001', 'Technology - Fundamental Concepts', 'Essential hardware, computing architecture, and IT concepts for PhilNITS IP & FE.', NULL, 12, 'medium', true, timezone('utc'::text, now()), timezone('utc'::text, now())),
('d1000000-0000-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000002', 'Management - PMBOK & ITIL Services', 'Project lifecycle, WBS, EVM, risk planning, SLA, and ITSM frameworks.', NULL, 12, 'medium', true, timezone('utc'::text, now()), timezone('utc'::text, now())),
('d1000000-0000-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000003', 'Strategy - Governance, Laws & Enterprise', 'COSO internal controls, CSR, software copyrights, patents, and business strategy models.', NULL, 12, 'hard', true, timezone('utc'::text, now()), timezone('utc'::text, now())),
('d1000000-0000-0000-0000-000000000004', 6, 'c1000000-0000-0000-0000-000000000004', 'Computer Systems & Architecture Review', 'Instruction cycles, caching hierarchies, CPU pipelining hazards, and buses.', NULL, 12, 'hard', true, timezone('utc'::text, now()), timezone('utc'::text, now())),
('d1000000-0000-0000-0000-000000000005', 6, 'c1000000-0000-0000-0000-000000000005', 'Algorithms, Data Structures & Big-O', 'Stacks, queues, binary trees, sorting algorithms, and complexity analysis.', NULL, 12, 'hard', true, timezone('utc'::text, now()), timezone('utc'::text, now())),
('d1000000-0000-0000-0000-000000000006', 6, 'c1000000-0000-0000-0000-000000000006', 'Networks & Cybersecurity Fundamentals', 'OSI 7 layers, TCP/IP, subnetting, symmetric/asymmetric encryption, and defenses.', NULL, 12, 'medium', true, timezone('utc'::text, now()), timezone('utc'::text, now())),
