INSERT INTO public.multiple_choice_questions (id, admin_id, category_id, prompt, options, correct_index, explanation, difficulty, sort_order, is_published, created_at, updated_at, review_speed)
VALUES
('e1000000-0100-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000001', 'Which internal CPU register holds the memory address of the next instruction to be fetched and executed?', '["Program Counter (PC)","Instruction Register (IR)","Memory Buffer Register (MBR)","Accumulator (ACC)"]', 0, 'The Program Counter (PC) stores the address of the next instruction in memory.', 'easy', 100, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0100-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000001', 'In the Von Neumann computer architecture, which sequence accurately depicts the standard instruction execution cycle?', '["Fetch -> Decode -> Execute -> Writeback","Decode -> Fetch -> Execute -> Interrupt","Execute -> Fetch -> Decode -> Store","Fetch -> Execute -> Decode -> Writeback"]', 0, 'The CPU first fetches instruction from memory, decodes opcodes, executes operations, and writes results back.', 'medium', 101, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0100-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000001', 'During an interrupt-driven I/O operation in a processor, what action does the CPU perform immediately after acknowledging the interrupt request (INTR)?', '["Saves the current Program Counter and processor state (PSW) onto the stack and jumps to the Interrupt Service Routine (ISR)","Immediately resets the entire memory address bus and clears all general registers","Halts all peripheral clock signals until the user presses an input button","Flushes all RAM data to persistent disk storage"]', 0, 'The CPU pushes the return address (PC) and processor status word (PSW) onto the stack before loading the ISR vector address.', 'hard', 102, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0200-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000004', 'Which type of memory is the fastest and positioned directly on or closest to the CPU core?', '["L1 Cache","DRAM Main Memory","NVMe SSD","Virtual Memory Swap"]', 0, 'L1 Cache is built directly into CPU execution cores and provides sub-nanosecond access speeds.', 'easy', 103, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0200-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000004', 'Which cache write policy updates both the cache line and the underlying main memory simultaneously on every write operation?', '["Write-Through","Write-Back","Write-Allocate","Lazy Write"]', 0, 'Write-Through updates both cache and main RAM simultaneously, ensuring consistent memory at the cost of bus bandwidth.', 'medium', 104, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0200-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000004', 'In computer architecture, what principle explains why loops and contiguous array traversals achieve very high cache hit ratios?', '["Temporal and Spatial Locality of Reference","Random Address Interleaving","Von Neumann Bottleneck Amplification","Instruction Pipelining Inversion"]', 0, 'Temporal locality (reusing recent data) and spatial locality (accessing adjacent memory addresses) maximize cache hits.', 'hard', 105, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0300-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000004', 'What is the primary performance benefit of instruction pipelining in a modern CPU?', '["Increases instruction execution throughput by overlapping stages","Reduces the execution latency of an individual instruction","Eliminates the need for RAM and secondary storage","Enables the CPU to run without an internal clock signal"]', 0, 'Pipelining allows multiple instructions to be processed in parallel across stages, increasing overall throughput.', 'easy', 106, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0300-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000004', 'Which type of pipeline hazard occurs when two instructions require access to the exact same hardware resource simultaneously?', '["Structural Hazard","Data Hazard","Control Hazard","Branch Hazard"]', 0, 'A structural hazard occurs when hardware cannot support all possible combinations of instructions in the same clock cycle.', 'medium', 107, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0300-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000004', 'What hardware optimization allows an ALU execution result to be passed directly to a dependent instruction without waiting for writeback to the register file?', '["Operand Forwarding (Bypassing)","Branch Prediction","Cache Flushing","Direct Memory Addressing"]', 0, 'Operand Forwarding routes output buffers of execution units directly to input muxes of subsequent pipeline stages.', 'hard', 108, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0400-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000002', 'In project management, what three interrelated variables constitute the traditional "Triple Constraint"?', '["Scope, Time, and Cost","Speed, Quality, and Marketing","Personnel, Hardware, and Software","Revenue, Profit, and Taxes"]', 0, 'The Triple Constraint (Iron Triangle) states that project success depends on balancing Scope, Time, and Cost.', 'easy', 109, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0400-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000002', 'What is the lowest deliverable level of decomposition in a Work Breakdown Structure (WBS) called?', '["Work Package","Milestone Task","Summary Phase","Control Account"]', 0, 'A Work Package is the lowest level in a WBS, small enough to be reliably estimated for cost and duration.', 'medium', 110, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0400-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000002', 'In Earned Value Management (EVM), if Planned Value (PV) = $100,000, Earned Value (EV) = $85,000, and Actual Cost (AC) = $95,000, what are the project status indicators?', '["Behind schedule (SPI = 0.85) and over budget (CV = -$10,000)","Ahead of schedule (SPI = 1.15) and under budget (CV = +$10,000)","On schedule (SPI = 1.0) and on budget (CV = $0)","Behind schedule (SPI = 0.90) and under budget (CV = +$5,000)"]', 0, 'SPI = EV / PV = 85k / 100k = 0.85 (<1 is behind schedule). CV = EV - AC = 85k - 95k = -$10k (negative is over budget).', 'hard', 111, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0500-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000002', 'What is a documented agreement between an IT service provider and its customers that defines required service levels and response times?', '["Service Level Agreement (SLA)","Non-Disclosure Agreement (NDA)","Master Services Agreement (MSA)","Memorandum of Understanding (MOU)"]', 0, 'An SLA specifies measurable performance metrics (uptime, response time, resolution limits) between provider and client.', 'easy', 112, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0500-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000002', 'Which ITIL process evaluates, approves, and schedules modifications to IT services or infrastructure to minimize business disruption?', '["Change Management","Release Management","Service Catalog Management","Availability Management"]', 0, 'Change Management ensures standardized methods and procedures are used for efficient handling of all changes.', 'medium', 113, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0500-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000002', 'In ITIL configuration management, what centralized database stores records of all hardware, software, and networking assets along with their interdependencies?', '["Configuration Management Database (CMDB)","Universal Asset Repository (UAR)","Enterprise Resource Schema (ERS)","Centralized Inventory Ledger (CIL)"]', 0, 'The CMDB tracks Configuration Items (CIs) and their upstream/downstream relationships to support impact analysis.', 'hard', 114, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0600-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000003', 'What does the acronym CSR stand for in enterprise management and business ethics?', '["Corporate Social Responsibility","Customer Service Relations","Company Strategy Realization","Centralized System Requirements"]', 0, 'Corporate Social Responsibility (CSR) is a self-regulating business model helping firms be socially accountable.', 'easy', 115, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0600-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000003', 'Under the COSO Internal Control Integrated Framework, which component establishes the organizational "tone at the top" regarding ethical standards?', '["Control Environment","Risk Assessment","Control Activities","Monitoring Activities"]', 0, 'The Control Environment sets the tone of an organization, influencing the control consciousness of its people.', 'medium', 116, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0600-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000003', 'Which internal control principle dictates that no single employee should have complete end-to-end control over authorizing, executing, and reconciling a critical transaction?', '["Segregation of Duties (SoD)","Least Privilege Principle","Need-to-Know Policy","Defense-in-Depth"]', 0, 'Segregation of Duties prevents errors and fraud by dividing key tasks among multiple individuals.', 'hard', 117, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0700-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000003', 'Which form of intellectual property automatically protects computer program source code and documentation upon creation?', '["Copyright","Patent","Trademark","Industrial Design"]', 0, 'Software code is protected as a literary work under copyright law immediately upon expression in fixed tangible form.', 'easy', 118, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0700-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000003', 'Under Republic Act 10173 (Philippine Data Privacy Act of 2012), within what timeframe must a personal data breach involving sensitive personal info be reported to the National Privacy Commission (NPC)?', '["Within 72 hours of knowledge","Within 24 hours of knowledge","Within 7 business days","Within 30 calendar days"]', 0, 'RA 10173 mandates notification to the NPC and affected data subjects within 72 hours upon knowledge of a qualifying breach.', 'medium', 119, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0700-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000003', 'Which open-source software license is categorized as "strong copyleft", requiring any derivative work incorporating its code to be distributed under the same license terms?', '["GNU General Public License (GPL)","MIT License","Apache License 2.0","BSD 3-Clause License"]', 0, 'The GNU GPL is a strong copyleft license requiring modified or derived works to remain open source under the GPL.', 'hard', 120, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0800-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000003', 'In a SWOT analysis, which two quadrants evaluate internal organizational capabilities?', '["Strengths and Weaknesses","Opportunities and Threats","Strengths and Opportunities","Weaknesses and Threats"]', 0, 'Strengths and Weaknesses are internal factors within company control; Opportunities and Threats are external market factors.', 'easy', 121, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0800-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000003', 'According to Michael Porter, which generic competitive strategy aims to achieve the lowest production and operating costs in an industry?', '["Cost Leadership","Differentiation","Focus Differentiation","Blue Ocean Strategy"]', 0, 'Cost Leadership focuses on efficiency, scale economies, and aggressive cost reduction to underprice competitors.', 'medium', 122, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0800-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000003', 'In the BCG Growth-Share Matrix, a business unit with high market share in a mature, low-growth industry is classified as a:', '["Cash Cow","Star","Question Mark","Dog"]', 0, 'Cash Cows generate substantial cash surplus with minimal capital reinvestment needed due to low market growth.', 'hard', 123, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-0900-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000006', 'At which layer of the OSI 7-layer reference model do IP routing and packet forwarding take place?', '["Layer 3 (Network Layer)","Layer 2 (Data Link Layer)","Layer 4 (Transport Layer)","Layer 7 (Application Layer)"]', 0, 'The Network Layer (Layer 3) handles logical IP addressing, routing protocols, and packet path determination.', 'easy', 124, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-0900-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000006', 'What three-step packet exchange sequence does TCP utilize to establish a reliable connection between a client and server?', '["SYN -> SYN-ACK -> ACK","ACK -> SYN -> SYN-ACK","PING -> PONG -> ACK","HELLO -> READY -> CONNECT"]', 0, 'The TCP Three-Way Handshake starts with client SYN, server replies with SYN-ACK, and client completes with ACK.', 'medium', 125, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-0900-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000006', 'Given the IPv4 network 192.168.1.0/27, what is the subnet mask and how many usable host IP addresses are available in this subnet?', '["Subnet mask 255.255.255.224 with 30 usable hosts","Subnet mask 255.255.255.192 with 62 usable hosts","Subnet mask 255.255.255.240 with 14 usable hosts","Subnet mask 255.255.255.128 with 126 usable hosts"]', 0, '/27 leaves 5 host bits: 2^5 = 32 total addresses minus 2 (network & broadcast) = 30 usable hosts. 256 - 32 = 224.', 'hard', 126, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-1000-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000006', 'In information security, what three core pillars constitute the "CIA Triad"?', '["Confidentiality, Integrity, and Availability","Control, Inspection, and Authorization","Cryptography, Identity, and Authentication","Certificates, IPsec, and Antivirus"]', 0, 'The CIA Triad is the foundational security benchmark: Confidentiality, Integrity, and Availability.', 'easy', 127, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-1000-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000006', 'Which symmetric encryption standard uses a block size of 128 bits and key sizes of 128, 192, or 256 bits?', '["Advanced Encryption Standard (AES)","Data Encryption Standard (DES)","RSA Public Key Cipher","MD5 Message Digest"]', 0, 'AES is the global symmetric block cipher standard established by NIST to replace DES and 3DES.', 'medium', 128, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-1000-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000006', 'When Alice sends a digitally signed, confidential email to Bob using Public Key Infrastructure (PKI), which keys are used for signing and encryption?', '["Alice signs with Alice''s private key; Alice encrypts with Bob''s public key","Alice signs with Bob''s public key; Alice encrypts with Alice''s private key","Alice signs with Alice''s public key; Alice encrypts with Bob''s private key","Alice signs and encrypts using Bob''s shared symmetric key only"]', 0, 'Signing uses the sender''s private key (proving authenticity); encryption uses the recipient''s public key (ensuring only Bob can read it).', 'hard', 129, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-1100-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000005', 'Which data structure operates strictly on the Last-In, First-Out (LIFO) access principle?', '["Stack","Queue","Array","Linked List"]', 0, 'A Stack is a LIFO data structure where elements are pushed and popped from the same end (top).', 'easy', 130, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-1100-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000005', 'What is the average time complexity of searching for an item in a balanced Binary Search Tree (BST) containing N nodes?', '["O(log N)","O(N)","O(1)","O(N^2)"]', 0, 'A balanced BST cuts the remaining search space in half with every node comparison, taking O(log N) time on average.', 'medium', 131, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-1100-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000005', 'What is the worst-case time complexity of the Quicksort algorithm, and when does it typically occur?', '["O(N^2), occurring when the chosen pivot is consistently the smallest or largest element on an already sorted array","O(N log N), occurring on randomly shuffled arrays","O(log N), occurring when using median-of-three pivot selection","O(N^3), occurring when duplicate elements are present"]', 0, 'Quicksort degrades to O(N^2) if the pivot creates unbalanced partitions of size 0 and N-1 repeatedly.', 'hard', 132, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e1000000-1200-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000008', 'In a relational database, what constraint uniquely identifies each record in a table and prevents duplicate or NULL values?', '["Primary Key","Foreign Key","Index Key","Check Constraint"]', 0, 'A Primary Key enforces entity integrity by ensuring every record has a unique, non-null identifier.', 'easy', 133, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e1000000-1200-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000008', 'Which relational database normal form requires eliminating partial functional dependencies so that all non-key attributes depend on the entire primary key?', '["Second Normal Form (2NF)","First Normal Form (1NF)","Third Normal Form (3NF)","Boyce-Codd Normal Form (BCNF)"]', 0, '2NF requires 1NF compliance and that non-prime attributes are fully functionally dependent on the entire composite key.', 'medium', 134, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e1000000-1200-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000008', 'In database transaction management, what property ensures that all operations in a transaction either complete entirely or are completely rolled back upon failure?', '["Atomicity","Consistency","Isolation","Durability"]', 0, 'Atomicity (the A in ACID) guarantees the "all-or-nothing" execution of database transactions.', 'hard', 135, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed')
INSERT INTO public.true_false_questions (id, admin_id, category_id, statement, answer, explanation, difficulty, sort_order, is_published, created_at, updated_at, review_speed)
VALUES
('e2000000-0100-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000001', 'The Program Counter (PC) stores the memory address of the next instruction to execute.', true, 'True. The Program Counter increments after each instruction fetch to point to the next instruction.', 'easy', 100, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0100-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000001', 'The Memory Address Register (MAR) holds the actual instruction opcodes currently being decoded by the Control Unit.', false, 'False. The Instruction Register (IR) holds the opcode being decoded; the MAR holds the address in memory.', 'medium', 101, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0100-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000001', 'Direct Memory Access (DMA) completely eliminates the CPU from ever configuring or initiating block data transfers.', false, 'False. The CPU must initially configure the DMA controller with source/destination addresses and byte count.', 'hard', 102, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0200-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000004', 'SRAM is widely used for main system RAM because it is cheaper and denser than DRAM.', false, 'False. DRAM is cheaper and denser (used for main RAM); SRAM is faster and more expensive (used for CPU cache).', 'easy', 103, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0200-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000004', 'In a Write-Back cache policy, main memory is updated only when the modified (dirty) cache line is evicted.', true, 'True. Write-back reduces memory bus writes by marking modified cache lines as dirty until eviction.', 'medium', 104, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0200-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000004', 'Spatial locality states that items with memory addresses near recently referenced items are likely to be accessed soon.', true, 'True. Array indexing and sequential code execution exhibit strong spatial locality.', 'hard', 105, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0300-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000004', 'Instruction pipelining decreases the execution latency of an individual instruction.', false, 'False. Pipelining increases instruction throughput, but individual instruction latency may slightly increase due to pipeline registers.', 'easy', 106, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0300-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000004', 'Data hazards occur when an instruction depends on the result of a previous instruction that has not yet completed execution.', true, 'True. Read-After-Write (RAW) data dependencies cause pipeline stalls unless bypassed or forwarded.', 'medium', 107, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0300-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000004', 'A branch penalty in a pipelined CPU occurs because instructions fetched after a branch must be flushed if the branch is taken.', true, 'True. Mispredicted branch instructions must be flushed from pipeline stages, causing branch penalty cycles.', 'hard', 108, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0400-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000002', 'A project is defined as an ongoing, continuous operational process within an enterprise.', false, 'False. A project is a temporary endeavor undertaken to create a unique product, service, or result.', 'easy', 109, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0400-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000002', 'The Critical Path in a project network diagram represents the sequence of dependent tasks that has zero total float.', true, 'True. The Critical Path determines the shortest possible project completion time; any delay delays the entire project.', 'medium', 110, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0400-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000002', 'In Earned Value Management, a Cost Performance Index (CPI) greater than 1.0 indicates that the project is running over budget.', false, 'False. CPI = EV / AC. A CPI > 1.0 means you are getting more than $1 of value per dollar spent (under budget).', 'hard', 111, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0500-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000002', 'Incident Management aims to analyze and permanently eliminate the root cause of IT disruptions.', false, 'False. Incident Management focuses on rapid service restoration. Problem Management analyzes and eliminates root causes.', 'easy', 112, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0500-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000002', 'A Workaround is a temporary method to resolve an incident when a permanent root-cause fix is not yet available.', true, 'True. Workarounds restore normal service while Problem Management continues root-cause investigation.', 'medium', 113, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0500-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000002', 'An Operational Level Agreement (OLA) is an agreement made between an IT service provider and external paying commercial clients.', false, 'False. An OLA is an internal agreement between different internal departments of the same organization; SLAs face external customers.', 'hard', 114, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0600-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000003', 'Corporate governance is solely concerned with maximizing executive bonuses and financial profits.', false, 'False. Corporate governance establishes accountability, fairness, and transparency for shareholders and stakeholders.', 'easy', 115, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0600-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000003', 'Whistleblower protection policies protect employees from retaliation when reporting internal corporate fraud or illegal conduct.', true, 'True. Whistleblower mechanisms are essential internal control practices mandated by corporate governance codes.', 'medium', 116, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0600-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000003', 'Under segregation of duties, the system administrator who develops application code should also have unrestricted permissions to deploy code directly to production.', false, 'False. Separating development and production deployment permissions is a core audit and security control.', 'hard', 117, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0700-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000003', 'A software patent protects the underlying mathematical algorithm in the abstract without any technical apparatus implementation.', false, 'False. Pure abstract mathematical algorithms are not patentable; patents require novel, industrial technical applications.', 'easy', 118, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0700-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000003', 'Under RA 10173, consent of the data subject must be clear, evidenced by written, electronic, or recorded means, and cannot be implied by silence.', true, 'True. Valid consent requires explicit, informed, and documented agreement from the data subject.', 'medium', 119, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0700-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000003', 'Permissive licenses such as MIT or BSD require developers to disclose the source code of all proprietary software that links to them.', false, 'False. Permissive licenses allow code to be used in proprietary commercial applications without source code disclosure.', 'hard', 120, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0800-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000003', 'In SWOT analysis, external competitor pricing and regulatory changes are classified as Opportunities or Threats.', true, 'True. Competitor behavior and regulations exist in the external environment outside direct organizational control.', 'easy', 121, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0800-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000003', 'In Porter''s Five Forces model, high switching costs for customers increase the bargaining power of buyers.', false, 'False. High switching costs make it difficult for buyers to leave, which decreases the bargaining power of buyers.', 'medium', 122, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0800-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000003', 'In the BCG Matrix, cash generated by "Cash Cows" should typically be reinvested to turn "Dogs" into market leaders.', false, 'False. Cash Cow profits are reinvested into Question Marks and Stars; Dogs are usually divested or liquidated.', 'hard', 123, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-0900-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000006', 'TCP is an unreliable, connectionless transport protocol that does not guarantee packet delivery order.', false, 'False. TCP provides reliable, connection-oriented, ordered byte streams. UDP is the connectionless, unreliable protocol.', 'easy', 124, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-0900-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000006', 'An IPv4 address consists of 32 bits divided into four 8-bit octets.', true, 'True. IPv4 addresses are 32 bits (e.g. 192.168.1.1), while IPv6 addresses are 128 bits.', 'medium', 125, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-0900-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000006', 'Address Resolution Protocol (ARP) translates known IP addresses into local physical MAC addresses on a local subnet.', true, 'True. ARP broadcasts request frames to map a known Layer 3 IP address to a Layer 2 hardware MAC address.', 'hard', 126, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-1000-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000006', 'Symmetric key cryptography uses two mathematically paired keys: a public key for encryption and a private key for decryption.', false, 'False. Symmetric cryptography uses the exact same shared secret key for encryption and decryption. Asymmetric uses paired keys.', 'easy', 127, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-1000-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000006', 'A digital signature provides non-repudiation because it is generated using the sender''s private key.', true, 'True. Only the private key holder could have generated the signature, preventing the sender from denying transmission.', 'medium', 128, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-1000-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000006', 'A Certificate Authority (CA) signs digital certificates using its own private key to bind an applicant''s identity to their public key.', true, 'True. Browsers verify digital certificates using the trusted CA''s pre-installed public root certificate.', 'hard', 129, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-1100-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000005', 'Binary search can be performed directly on an unsorted array with O(log n) time complexity.', false, 'False. Binary search strictly requires the array to be sorted first. On unsorted arrays, linear search is O(n).', 'easy', 130, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-1100-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000005', 'A Queue data structure operates on a First-In, First-Out (FIFO) principle, enqueuing at the rear and dequeuing from the front.', true, 'True. Queues preserve arrival order, making them ideal for printer spooling and CPU process scheduling.', 'medium', 131, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-1100-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000005', 'An in-order tree traversal of a Binary Search Tree (Left, Root, Right) outputs the node values in non-decreasing sorted order.', true, 'True. In-order traversal visits left subtree (smaller), current node, and right subtree (larger), producing sorted keys.', 'hard', 132, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e2000000-1200-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000008', 'A Primary Key column in a relational database table is permitted to store NULL values.', false, 'False. Primary keys must be unique and NOT NULL to ensure entity integrity.', 'easy', 133, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e2000000-1200-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000008', 'Third Normal Form (3NF) requires a relation to be in 2NF and have no transitive functional dependencies between non-key attributes.', true, 'True. 3NF removes transitive dependencies (e.g. non-key column A determining non-key column B).', 'medium', 134, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e2000000-1200-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000008', 'A LEFT OUTER JOIN in SQL returns only the rows where there is a matching record in both the left and right tables.', false, 'False. That describes an INNER JOIN. A LEFT JOIN returns all rows from the left table and matched rows from the right table (NULL if no match).', 'hard', 135, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed')
INSERT INTO public.flashcards (id, deck_id, admin_id, term, definition, hint, sort_order, created_at, updated_at, review_speed)
VALUES
('e3000000-0100-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000001', 6, 'Program Counter (PC)', 'CPU register that holds the memory address of the next instruction to be fetched.', 'Directs the CPU to the next execution step.', 100, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0100-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000001', 6, 'Instruction Execution Cycle', 'Continuous process comprising Fetch, Decode, Execute, and Writeback stages performed by the CPU.', 'The foundational cycle of all Von Neumann processors.', 101, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0100-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000001', 6, 'Direct Memory Access (DMA)', 'Specialized hardware mechanism allowing high-speed I/O devices to transfer data directly to/from RAM without continuous CPU intervention.', 'Frees CPU cycles during large bulk data transfers.', 102, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0200-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000004', 6, 'Cache Memory', 'High-speed SRAM located close to or on the CPU die to bridge the processor-memory speed bottleneck.', 'Extremely fast memory holding frequently accessed data.', 103, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0200-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000004', 6, 'Write-Back Policy', 'Cache policy where updates are written only to cache and marked dirty; main memory is updated only when the line is replaced.', 'Saves memory bus write bandwidth.', 104, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0200-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000004', 6, 'Locality of Reference', 'Phenomenon where programs access a relatively small portion of address space at any given time (Temporal and Spatial).', 'The foundational principle that makes cache memory effective.', 105, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0300-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000004', 6, 'Instruction Pipelining', 'Technique where execution of multiple instructions is overlapped across sequential hardware stages.', 'Analogous to an industrial assembly line.', 106, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0300-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000004', 6, 'Data Hazard', 'Condition where pipeline instructions cannot execute because required operands have not yet been produced by earlier instructions.', 'Solved by forwarding or inserting pipeline stalls (bubbles).', 107, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0300-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000004', 6, 'Operand Forwarding', 'Hardware data path routing computed results directly from ALU/MEM stages to waiting instructions, eliminating pipeline stalls.', 'Bypasses writing back to the register file first.', 108, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0400-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000002', 6, 'Triple Constraint', 'Core project management model balancing Scope, Time, and Cost constraints against Quality.', 'Altering one constraint directly impacts the others.', 109, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0400-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000002', 6, 'Work Breakdown Structure (WBS)', 'Hierarchical decomposition of total project scope into manageable, deliverable-oriented work packages.', 'Visual breakdown organizing project team deliverables.', 110, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0400-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000002', 6, 'Earned Value Management (EVM)', 'Objective project performance measurement technique comparing Planned Value (PV), Earned Value (EV), and Actual Cost (AC).', 'Calculates Cost and Schedule variances and indices.', 111, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0500-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000002', 6, 'Service Level Agreement (SLA)', 'Contractual commitment defining target service levels, availability percentages, and escalation response times for IT services.', 'Sets clear customer expectations for service quality.', 112, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0500-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000002', 6, 'Problem Management', 'ITIL process dedicated to identifying root causes of incidents and providing permanent error resolutions to prevent recurrence.', 'Focuses on prevention rather than immediate restore.', 113, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0500-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000002', 6, 'CMDB', 'Central repository storing information about Configuration Items (CIs) and their relational dependencies across the IT estate.', 'Crucial for impact analysis during change management.', 114, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0600-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000003', 6, 'Corporate Social Responsibility (CSR)', 'Business approach where organizations contribute positively to societal, economic, and environmental well-being.', 'Balancing profit with ethics and community impact.', 115, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0600-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000003', 6, 'COSO Framework', 'Internal control framework comprising Control Environment, Risk Assessment, Control Activities, Information & Communication, and Monitoring.', 'Standard benchmark for corporate internal controls.', 116, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0600-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000003', 6, 'Segregation of Duties (SoD)', 'Internal control policy requiring key tasks to be divided among different employees to reduce fraud risk and human error.', 'Prevents single-person fraud or unverified modifications.', 117, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0700-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000003', 6, 'Copyright in Software', 'Exclusive legal right granted to software authors protecting original code, syntax, and documentation from unauthorized copying.', 'Protects the expression of ideas, not the idea itself.', 118, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0700-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000003', 6, 'RA 10173 (Data Privacy Act)', 'Philippine national legislation protecting personal information privacy in government and private sector communications.', 'Mandates Data Protection Officers and 72-hour breach reporting.', 119, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0700-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000003', 6, 'Copyleft Licensing (GPL)', 'Licensing mechanism requiring derivative works of software to be released under the exact same open-source terms.', 'Contrasted with permissive licenses like MIT and Apache.', 120, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0800-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000003', 6, 'SWOT Analysis', 'Strategic tool analyzing internal Strengths/Weaknesses and external Opportunities/Threats.', 'Foundational 2x2 strategic planning matrix.', 121, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0800-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000003', 6, 'Porter''s Five Forces', 'Framework analyzing industry profitability: Rivalry, Threat of Entrants, Buyer Power, Supplier Power, and Threat of Substitutes.', 'Evaluates competitive intensity of a market.', 122, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0800-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000003', 6, 'BCG Growth-Share Matrix', 'Portfolio tool categorizing business units into Stars, Cash Cows, Question Marks, and Dogs based on market growth and market share.', 'Guides capital allocation across business units.', 123, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-0900-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000006', 6, 'Network Layer (Layer 3)', 'OSI layer responsible for logical addressing (IPv4/IPv6), packet routing, and forwarding across networks.', 'Where routers and IP addresses operate.', 124, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-0900-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000006', 6, 'Three-Way Handshake', 'Process used by TCP to establish a connection using synchronize (SYN) and acknowledge (ACK) packets.', 'SYN, SYN-ACK, ACK handshake sequence.', 125, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-0900-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000006', 6, 'Address Resolution Protocol (ARP)', 'Network protocol used to map an Internet Protocol (IP) address to a physical Media Access Control (MAC) address.', 'Bridges Layer 3 logical IP and Layer 2 hardware MAC.', 126, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-1000-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000006', 6, 'CIA Triad', 'Three primary security principles: Confidentiality (privacy), Integrity (accuracy), and Availability (accessibility).', 'Foundational framework of information security.', 127, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-1000-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000006', 6, 'Asymmetric Cryptography', 'Cryptographic system using public and private key pairs for encryption and digital signatures (e.g. RSA, ECC).', 'Public key encrypts; private key decrypts.', 128, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-1000-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000006', 6, 'Digital Signature', 'Mathematical technique validating authenticity and integrity of a message; created with sender''s private key and verified with public key.', 'Provides authentication, integrity, and non-repudiation.', 129, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-1100-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000005', 6, 'Stack (LIFO)', 'Abstract linear data structure operating on Last-In, First-Out where push and pop occur at the top.', 'Like a stack of dinner plates.', 130, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-1100-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000005', 6, 'Binary Search Algorithm', 'Efficient search algorithm for sorted lists that repeatedly divides search interval in half with O(log n) performance.', 'Requires sorted input array.', 131, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-1100-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000005', 6, 'Quicksort Algorithm', 'Divide-and-conquer sorting algorithm partitioning an array around a pivot; O(n log n) average, O(n^2) worst case.', 'In-place sorting using recursive partition.', 132, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed'),
('e3000000-1200-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000008', 6, 'Primary Key', 'Column or set of columns uniquely identifying each row in a relational database table; cannot be null.', 'Guarantees entity integrity in a table.', 133, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Quick'),
('e3000000-1200-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000008', 6, 'Database Normalization', 'Process of structuring relational database tables to reduce data redundancy and eliminate update/delete anomalies.', '1NF (atomic), 2NF (no partial), 3NF (no transitive).', 134, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Standard'),
('e3000000-1200-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000008', 6, 'ACID Properties', 'Four core transaction guarantees: Atomicity (all-or-nothing), Consistency (rules kept), Isolation (concurrency), Durability (persisted).', 'Foundational transaction reliability guarantees.', 135, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Detailed')
INSERT INTO public.matching_pairs (id, admin_id, category_id, set_title, term, definition, sort_order, is_published, created_at, updated_at, explanation_slow, explanation_fast, review_speed)
VALUES
('e4000000-0100-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000001', 'Computer Architecture', 'Program Counter', 'Register holding address of next instruction', 100, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Program Counter (PC) automatically increments during fetch stage to sequence instruction execution.', 'Tracks next instruction address in RAM.', 'Quick'),
('e4000000-0100-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000001', 'Computer Architecture', 'Instruction Register (IR)', 'Holds the instruction currently being decoded', 101, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Instruction Register (IR) receives fetched instructions from memory data bus for decoding by the Control Unit.', 'Stores active opcode for CU decoding.', 'Standard'),
('e4000000-0100-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000001', 'Computer Architecture', 'DMA Controller', 'Transfers bulk data directly between I/O and RAM', 102, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'DMA controller manages memory bus directly, transferring large data blocks and interrupting CPU only upon completion.', 'Bypasses CPU for high-speed I/O transfers.', 'Detailed'),
('e4000000-0200-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000004', 'Memory Hierarchy', 'L1 Cache', 'Fastest on-chip cache built directly into CPU core', 103, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Level 1 cache is dedicated to individual CPU cores with single-cycle access latency for instructions and data.', 'Fastest level of cache on the CPU die.', 'Quick'),
('e4000000-0200-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000004', 'Memory Hierarchy', 'Write-Through', 'Writes simultaneously to cache and main memory', 104, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Write-through guarantees data consistency across main memory and cache at the cost of higher bus write traffic.', 'Immediate dual write to cache and RAM.', 'Standard'),
('e4000000-0200-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000004', 'Memory Hierarchy', 'Spatial Locality', 'Likelihood of accessing nearby contiguous addresses', 105, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Spatial locality ensures pre-fetching contiguous memory blocks into cache lines significantly reduces cache miss penalties.', 'Tendency to read adjacent data blocks.', 'Detailed'),
('e4000000-0300-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000004', 'Pipelining & Hazards', 'Instruction Throughput', 'Number of instructions completed per unit of time', 106, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Pipelining maximizes instruction throughput towards an ideal IPC (instructions per cycle) of 1.0.', 'Rate of instructions finished by the CPU.', 'Quick'),
('e4000000-0300-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000004', 'Pipelining & Hazards', 'Structural Hazard', 'Conflict arising when instructions compete for hardware', 107, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Structural hazards occur when memory or functional units are simultaneously requested by multiple pipeline stages.', 'Hardware resource bottleneck in pipeline.', 'Standard'),
('e4000000-0300-0000-0000-000000000003', 6, 'c1000000-0000-0000-0000-000000000004', 'Pipelining & Hazards', 'Operand Forwarding', 'Feeds ALU outputs directly to dependent pipeline stages', 108, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Operand forwarding routes intermediate pipeline register outputs to ALU inputs to resolve RAW data hazards.', 'Bypasses register writeback to eliminate stalls.', 'Detailed'),
('e4000000-0400-0000-0000-000000000001', 6, 'c1000000-0000-0000-0000-000000000002', 'Project Management', 'Triple Constraint', 'Interrelated balance of Scope, Time, and Cost', 109, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'The Triple Constraint demonstrates that changing scope inevitably alters either schedule time or project budget.', 'Core project constraints triangle.', 'Quick'),
('e4000000-0400-0000-0000-000000000002', 6, 'c1000000-0000-0000-0000-000000000002', 'Project Management', 'Work Package', 'Lowest level deliverable in a WBS structure', 110, true, timezone('utc'::text, now()), timezone('utc'::text, now()), 'Work packages can be assigned to single owners with discrete schedule duration and budget allocation.', 'Manageable unit of work in WBS.', 'Standard'),
